#!/usr/bin/env bash
# batch_p06b_killswitch.sh
#
# P0.6 Batch B — the real gateway-side kill-switch (spec: prompts/P0_DEEPSEEK_PROMPT.md,
# architecture/02_RISK_SOLUTIONS_21.md). Adds gateway/src/killswitch.js: a
# dedicated redis-cache pub/sub subscriber + command connection, an in-memory
# global/tenant/channel scope cache, strictest-wins effective-state
# computation, and the staleness fail-closed rule for marketing/broadcast
# (KS_STALE_MAX_S). Wires it into outbound/queue.js (replaces the P0.4-era
# always-allow stub; a blocked item now becomes failed(error_class='blocked')
# instead of being silently requeued forever) and index.js (an immediate
# HTTP 423 {error:'blocked_by_switch', capability, state, scope} at
# POST /sessions/:id/send request time). See docs/P0_DEVIATIONS.md D-23/D-24/D-25
# for the real architectural gap this batch works within (no session anywhere
# in this codebase carries tenant_id/channel_account_id yet - confirmed by
# grep, not assumed - so every real check today resolves through the spec's
# own documented global-only fallback) and the kind->capability mapping
# decision. See docs/P0_FINDINGS.md F11 for a real bug (a missing "wait for
# Redis ready before the first command" step) caught and fixed during this
# batch's own local self-validation, before ever reaching this script.
#
# This script only WRITES the files below and re-runs verification (syntax
# checks + the FULL real-Redis test suite, including the new
# killswitch.test.js's real acceptance-matrix/propagation-latency/staleness
# tests) - it does NOT run `git add`/`git commit`. A separate
# batch_p06b_commit.sh (to follow once you confirm this passes here) does
# that, showing the diff and asking for y/N confirmation first, same as
# every previous batch in this project.
#
# IMPORTANT - a real infrastructure question this script cannot answer for
# you: does THIS VPS's docker-compose.yml actually define a separate
# `redis-cache` service (network alias `redis-cache`), and does the real
# `gateway` service's environment already set REDIS_CACHE_HOST/PORT to it?
# gateway/.env.example already had a REDIS_CACHE_PASSWORD placeholder from an
# earlier phase, which suggests yes - but this script does not check or
# assume docker-compose.yml/.env's actual contents. If REDIS_CACHE_HOST is
# unset in the real gateway container's environment, killswitch.js falls
# back to 127.0.0.1:6379 (the same default redis-durable itself uses) - if
# that is NOT where a real redis-cache is reachable on this VPS, the
# kill-switch subsystem will start in a permanently-stale (fail-closed for
# marketing/broadcast, open for everything else) state rather than crash the
# gateway (H3) - but it will not be doing anything useful until the real
# connection details are confirmed. Please paste `docker compose config` (or
# the relevant slice of docker-compose.yml + .env) for gateway/redis-cache
# once this batch is otherwise verified, so the next step can confirm (or
# fix) this before we consider Batch B's real-VPS acceptance test complete.
#
# Run from the repository root: /home/sharwa/sharwa_ai
set -euo pipefail

REPO_ROOT="/home/sharwa/sharwa_ai"
if [ ! -d "$REPO_ROOT/gateway" ]; then
  echo "ERROR: $REPO_ROOT/gateway not found. Run this script from a machine where the repo lives at $REPO_ROOT, or edit REPO_ROOT at the top of this script." >&2
  exit 1
fi
cd "$REPO_ROOT"

echo "=== [0/6] Pre-flight: repo root = $REPO_ROOT ==="
git rev-parse --is-inside-work-tree >/dev/null 2>&1 && echo "  git repo: OK" || { echo "ERROR: not a git repository" >&2; exit 1; }

echo ""
echo "=== [1/6] Writing files (base64-embedded, decoded in place) ==="

write_file() {
  local path="$1"
  mkdir -p "$(dirname "$path")"
  cat > "$path.b64.tmp"
  base64 -d "$path.b64.tmp" > "$path"
  rm -f "$path.b64.tmp"
  echo "  wrote: $path ($(wc -c < "$path") bytes)"
}

