echo ""
echo "=== [2/6] Syntax-check every changed/new JS file ==="
for f in gateway/src/config.js gateway/src/killswitch.js gateway/src/metrics.js \
         gateway/src/outbound/queue.js gateway/src/sessions.js gateway/src/index.js \
         gateway/src/__tests__/killswitch.test.js; do
  node --check "$f" && echo "  OK: $f"
done

echo ""
echo "=== [3/6] hunt_gate-equivalent grep: no empty catch / swallowed rejection introduced ==="
if grep -rn "catch (err) {}" gateway/src/config.js gateway/src/killswitch.js gateway/src/metrics.js \
     gateway/src/outbound/queue.js gateway/src/sessions.js gateway/src/index.js 2>/dev/null; then
  echo "ERROR: empty catch block found" >&2
  exit 1
fi
if grep -rn "\.catch(() => {})" gateway/src/config.js gateway/src/killswitch.js gateway/src/metrics.js \
     gateway/src/outbound/queue.js gateway/src/sessions.js gateway/src/index.js 2>/dev/null; then
  echo "ERROR: swallowed rejection found" >&2
  exit 1
fi
echo "  OK: no empty-catch / swallowed-rejection patterns found in changed files"

echo ""
echo "=== [4/6] Confirm redis-cache reachability question (informational only - does not fail the script) ==="
echo "  If this VPS's docker-compose.yml has a redis-cache service, gateway/scripts/run-tests.mjs's"
echo "  test container below should reach it at the network alias 'redis-cache:6379' automatically"
echo "  once docker-compose.yml's gateway service environment is confirmed - see the header comment"
echo "  of this script. This step does not check that; it only reminds you to paste"
echo "  'docker compose config' once step [5/6] below passes, so the real host/port can be confirmed."

echo ""
echo "=== [5/6] Full real-Redis test suite (npm test = gateway/scripts/run-tests.mjs) inside the real gateway image ==="
if ! command -v docker >/dev/null 2>&1; then
  echo "ERROR: docker not found - cannot run the real-Redis test suite." >&2
  exit 1
fi
DC="docker compose"
$DC version >/dev/null 2>&1 || DC="docker-compose"

$DC run --rm \
  -e ALLOW_FAKE_WA=1 \
  -e NODE_ENV=test \
  -e LOG_LEVEL=error \
  -e METRICS_TOKEN=test-token \
  -v "$(pwd)/gateway/src:/app/src:ro" \
  -v "$(pwd)/gateway/scripts:/app/scripts:ro" \
  -v "$(pwd)/gateway/test-support:/app/test-support:ro" \
  -v "$(pwd)/gateway/package.json:/app/package.json:ro" \
  gateway npm test

echo ""
echo "=== [6/6] Review: git status / diff --stat (NO commit performed by this script) ==="
git status --short
echo ""
git diff --stat -- gateway/src/config.js gateway/src/killswitch.js gateway/src/metrics.js \
  gateway/src/outbound/queue.js gateway/src/sessions.js gateway/src/index.js gateway/.env.example \
  gateway/src/__tests__/killswitch.test.js docs/P0_DEVIATIONS.md docs/P0_FINDINGS.md || true

echo ""
echo "=== Done. Nothing was committed. ==="
echo "If [5/6] shows every test passing (the exact new total will include the 10 new killswitch.test.js"
echo "cases on top of whatever this repo's current total is), please also paste 'docker compose config'"
echo "(or the gateway/redis-cache slice of docker-compose.yml + this VPS's real .env) so REDIS_CACHE_HOST/PORT"
echo "can be confirmed against what killswitch.js will actually connect to in production - see this"
echo "script's header comment. Once both are confirmed, I will prepare batch_p06b_commit.sh."
